package com.careflow.hospital.reservations;
import com.careflow.hospital.audit.AuditService;import com.careflow.hospital.departments.*;import com.careflow.hospital.doctors.*;import com.careflow.hospital.patients.*;import com.careflow.hospital.scheduling.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class ReservationServiceTest {SlotReservationRepository reservations=mock(SlotReservationRepository.class);PatientRepository patients=mock(PatientRepository.class);DoctorRepository doctors=mock(DoctorRepository.class);DepartmentRepository departments=mock(DepartmentRepository.class);SlotGenerationService slots=mock(SlotGenerationService.class);AuditService audit=mock(AuditService.class);ReservationService service;UUID userId=UUID.randomUUID(),patientId=UUID.randomUUID(),doctorId=UUID.randomUUID(),departmentId=UUID.randomUUID();Patient patient=mock(Patient.class);Doctor doctor=mock(Doctor.class);Department department=mock(Department.class);Instant start=Instant.now().plusSeconds(86400),end=start.plusSeconds(1800);
 @BeforeEach void setup(){service=new ReservationService(reservations,patients,doctors,departments,slots,audit);when(patient.getId()).thenReturn(patientId);when(patient.isProfileComplete()).thenReturn(true);when(patients.findByUserId(userId)).thenReturn(Optional.of(patient));when(doctor.isActive()).thenReturn(true);when(doctor.getId()).thenReturn(doctorId);when(doctor.getDepartmentId()).thenReturn(departmentId);when(doctors.findByIdForUpdate(doctorId)).thenReturn(Optional.of(doctor));when(department.isActive()).thenReturn(true);when(department.getId()).thenReturn(departmentId);when(department.getTimezone()).thenReturn("UTC");when(departments.findById(departmentId)).thenReturn(Optional.of(department));when(slots.generate(eq(departmentId),eq(doctorId),any())).thenReturn(List.of(new SlotDtos.Slot(doctorId,"Dr Test","Medicine",start,end,30,"UTC")));when(reservations.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
 @Test void reservesAnAuthoritativeSlotForFiveMinutes(){var view=service.create(userId,new ReservationDtos.Create(doctorId,start));assertEquals(start,view.startsAt());assertEquals("ACTIVE",view.status());assertTrue(view.expiresAt().isAfter(Instant.now().plusSeconds(290)));verify(doctors).findByIdForUpdate(doctorId);verify(audit).record(eq(userId),eq("SLOT_RESERVED"),eq("SLOT_RESERVATION"),any(),eq("SUCCESS"));}
}
